// tools/instrument/gen.mjs
// ---------------------------------------------------------------------------
// Emit a self-feeding micro-contract that invokes ONE target function `loops`
// times inside a `for` loop, chaining a rolling W-int state so every call is
// data-dependent (optimiser cannot drop it) and operands stay full ~254-bit Fp.
//
// State: s0..s{W-1}, W = max(inN, outN, 4). Each iteration:
//   * read inN state ints (s0..s{inN-1}) as the call's args,
//   * write the outN results into o0..o{outN-1},
//   * fold them back: rotate state by xoring/replacing the low outN slots, and
//     mix one int forward so the chain can never be constant-folded.
// At loop end we `require` a cheap predicate on the state so the whole thing is
// live. The loop variable, bounds, state declarations and fold glue are IDENTICAL
// across (a) different `loops` counts and (b) the glue-only variant, so the
// differential isolates the target call. See unit-costs.mjs.
//
// mode:
//   'call'  -> body invokes the target.
//   'glue'  -> body replaces the target with an identity producing outN ints
//              from current state (NO field arithmetic), same fold-back glue.
// ---------------------------------------------------------------------------
import { defsFor, TARGETS } from './funcs.mjs';

// pad: number of EXTRA live locals declared before the loop and kept live via the
// final liveness sum. This raises the stack depth at the call site so the target's
// argument OP_PICKs are as deep as in miller4.millerSingle (which holds ~18 live
// locals: f=12 + R=6). Per-call base scales linearly with this depth (validated:
// +~457 instr per +8 locals for `line`), so matching it makes the differential
// reproduce the real per-call-site base without any post-hoc calibration.
export function genContract(name, loops, mode, pad = 0) {
  const t = TARGETS[name];
  if (!t) throw new Error(`unknown target ${name}`);
  const W = Math.max(t.inN, t.outN, 4);

  // modes:
  //   'call'  -> loop body invokes the target: bind outN returns, fold back.
  //   'empty' -> loop body does ONLY a minimal state churn (s0 = s0 + 1) to stay
  //              live; NO call, NO output binding, NO fold. Its marginal is the
  //              pure loop-control overhead (i<N test, i=i+1, branch + 1 add).
  //
  // unit = callMarginal - emptyMarginal therefore RETAINS, inside the call cost,
  // the full per-call-site structure that also runs in miller4: pushing inN args
  // (deep-local OP_PICKs), the OP_INVOKE, binding outN returns, and folding them
  // into locals. We deliberately do NOT subtract that (an earlier 'glue' baseline
  // that reproduced the return-binding under-counted base/instr by ~2x because it
  // cancelled real per-call-site marshalling). See diag in unit-costs.mjs.
  const isEmpty = mode === 'empty';
  const defs = isEmpty ? '' : defsFor(t.call);

  const seedParams = Array.from({ length: W }, (_, i) => `int z${i}`).join(', ');
  const stateInit = Array.from({ length: W }, (_, i) => `        int s${i} = z${i};`).join('\n');
  // extra live locals to match miller4 call-site stack depth (see header)
  const padInit = pad > 0
    ? '\n' + Array.from({ length: pad }, (_, i) => `        int p${i} = z${i % W} + ${i + 1};`).join('\n')
    : '';
  const callArgs = Array.from({ length: t.inN }, (_, i) => `s${i}`).join(', ');

  const outBind = Array.from({ length: t.outN }, (_, i) => `o${i}`);
  const outDecl = t.outN === 1 ? `int o0` : `(${outBind.map((o) => `int ${o}`).join(', ')})`;

  let bodyLines = [];
  if (isEmpty) {
    // minimal churn so the loop has a data dependency and stays live; matches the
    // loop-control instructions of 'call' mode but nothing else.
    bodyLines.push(`            s0 = s0 + 1;`);
  } else {
    bodyLines.push(`            ${outDecl} = ${t.call}(${callArgs});`);
    // fold-back (= the call's return-binding into locals; KEPT in the unit since
    // miller4 also binds every call's results into locals). Rewrite low slots with
    // outputs so each iteration depends on the previous, keeping operands ~field-
    // sized (call outputs are mod-reduced).
    const nLow = Math.min(t.outN, W);
    for (let i = 0; i < nLow; i++) bodyLines.push(`            s${i} = o${i};`);
    for (let i = nLow; i < W; i++) bodyLines.push(`            s${i} = o${i % t.outN} + ${i};`);
  }
  const foldStr = bodyLines.join('\n');

  // liveness require referencing EVERY state slot (and pad local) so none is unused.
  const sumAll = Array.from({ length: W }, (_, i) => `s${i}`).join(' + ')
    + (pad > 0 ? ' + ' + Array.from({ length: pad }, (_, i) => `p${i}`).join(' + ') : '');
  const live = `        int chk = (${sumAll});\n        require(chk - chk + 1 == 1);`;

  return `pragma cashscript ^0.13.0;
// AUTO-GENERATED by tools/instrument/gen.mjs  target=${name} mode=${mode} loops=${loops}
contract Micro_${name}_${mode}() {
${defs}
    function spend(${seedParams}) {
${stateInit}${padInit}
        for (int i = 0; i < ${loops}; i = i + 1) {
${foldStr}
        }
${live}
    }
}
`;
}
